package net.civeira.phylax.features.document.themeversion.infrastructure.event;

import jakarta.enterprise.context.ApplicationScoped;
import jakarta.enterprise.event.Event;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.features.document.themeversion.domain.ThemeVersion;
import net.civeira.phylax.features.document.themeversion.domain.event.ThemeVersionEvent;

@ApplicationScoped
@RequiredArgsConstructor
public class ThemeVersionEventDispatcher {

  /**
   * @autogenerated EventDispatcherGenerator
   */
  private final Event<ThemeVersionEvent> emitter;

  /**
   * @autogenerated EventDispatcherGenerator
   * @param entity
   */
  public void dispatch(final ThemeVersion entity) {
    entity.getRecordedEvents().forEach(emitter::fire);
  }
}
